Aqui está a solução completa e otimizada para o problema **Candidatas**, estruturada conforme as etapas heurísticas do Método de Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA

- **Objetivo Central:** Manter uma sequência de inteiros $S$ sujeita a atualizações pontuais (tipo 1) e consultas por intervalo (tipo 2), onde deve-se contar quantas subsequências contíguas (subarrays) dentro do intervalo $[E, D]$ têm máximo divisor comum ($\text{mdc}$) estritamente maior do que 1.
- **Entrada:**
  - $N, M \le 10^5$.
  - Valores de $S_i, V \le 10^9$.
  - Operações: $1 \ I \ V$ (atualização pontual) ou $2 \ E \ D$ (consulta em intervalo).
- **Saída:** Para cada operação de consulta (tipo 2), imprimir em uma linha o total de subarrays candidatos.
- **Restrições e Cuidados:**
  - O número de subarrays em um intervalo pode chegar a $\frac{10^5 \times (10^5 + 1)}{2} \approx 5 \times 10^9$, excedendo o limite de 32 bits. Portanto, contadores e respostas devem usar `long long`.
  - A complexidade por operação precisa ser compatível com $10^5$ consultas em 1 ou 2 segundos.
  - O MDC decresce rapidamente ao longo de um prefixo ou sufixo. O número de valores distintos de MDC em qualquer prefixo ou sufixo é no máximo $\approx 30$ (pois cada mudança divide o MDC por pelo menos 2, e $2^{30} > 10^9$).

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

- **Estrutura de Dados:** Árvore de Segmentos (Segment Tree).
- **Informações em cada nó da SegTree:**
  - `ans` (`long long`): número total de subarrays candidatos contidos estritamente no intervalo coberto pelo nó.
  - `pref`: lista de pares `(g, len)`, representando os blocos contíguos de prefixos que possuem o mesmo $\text{mdc} = g$.
  - `suff`: lista de pares `(g, len)`, representando os blocos contíguos de sufixos que possuem o mesmo $\text{mdc} = g$.
  - `len` (`int`): comprimento do intervalo coberto pelo nó.
- **Operação de Fusão (`merge`) entre dois nós $A$ e $B$:**
  1. $\text{ans} = A\text{.ans} + B\text{.ans}$.
  2. Adicionar os subarrays que cruzam a fronteira entre $A$ e $B$: para cada bloco de sufixo $(g_1, c_1)$ de $A$ e cada bloco de prefixo $(g_2, c_2)$ de $B$, se $\gcd(g_1, g_2) > 1$, somamos $c_1 \times c_2$ a $\text{ans}$.
     - *Otimização crucial:* Se $g_1 = 1$, nunca teremos $\gcd(1, g_2) > 1$, então podemos ignorar ou interromper.
  3. Construir a lista de prefixos do novo nó: começa com os blocos de $A$. Se o último bloco de $A$ cobrir todo o nó $A$, estende-se pelos blocos de $B$ aplicando $\gcd(g_B, \text{gcd\_total}(A))$. Blocos consecutivos com o mesmo $\text{mdc}$ são mesclados.
  4. Analogamente para os sufixos.
- **Complexidade:**
  - Número de blocos em cada nó: no máximo $\approx 30$ (na prática $\le 10$).
  - Merge de dois nós: $O(K^2 \cdot \log(\min(A, B)))$ no pior caso, onde $K \le 30$. Na prática, a grande maioria dos números tem poucos fatores primos e $K$ raramente excede 6. Com a otimização de $\gcd$, cada merge é executado em microssegundos.
  - Tempo total: $O((N + M) \log N \cdot K^2)$ no pior caso, com constante prática minúscula. Espaço: $O(N)$ para a árvore.

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_BLOCKS 35

static inline int gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

typedef struct {
    int g;
    int cnt;
} Block;

typedef struct {
    long long ans;
    int len;
    int pref_sz;
    int suff_sz;
    Block pref[MAX_BLOCKS];
    Block suff[MAX_BLOCKS];
} Node;

#define MAXN 100005

int A[MAXN];
Node tree[4 * MAXN];

void make_leaf(Node *res, int val) {
    res->len = 1;
    res->pref_sz = 1;
    res->suff_sz = 1;
    res->pref[0].g = val;
    res->pref[0].cnt = 1;
    res->suff[0].g = val;
    res->suff[0].cnt = 1;
    res->ans = (val > 1) ? 1 : 0;
}

Node merge(const Node *L, const Node *R) {
    if (L->len == 0) return *R;
    if (R->len == 0) return *L;

    Node res;
    res.len = L->len + R->len;
    res.ans = L->ans + R->ans;

    /* Contar subarrays que cruzam a fronteira entre L e R */
    for (int i = 0; i < L->suff_sz; ++i) {
        int g1 = L->suff[i].g;
        if (g1 <= 1) continue;
        long long c1 = L->suff[i].cnt;
        for (int j = 0; j < R->pref_sz; ++j) {
            int g2 = R->pref[j].g;
            if (g2 <= 1) continue;
            if (gcd(g1, g2) > 1) {
                res.ans += c1 * R->pref[j].cnt;
            }
        }
    }

    /* Construir os blocos de prefixo de res */
    res.pref_sz = 0;
    for (int i = 0; i < L->pref_sz; ++i) {
        res.pref[res.pref_sz++] = L->pref[i];
    }

    int cur_len = 0;
    for (int i = 0; i < L->pref_sz; ++i) {
        cur_len += L->pref[i].cnt;
    }

    if (cur_len == L->len) {
        int total_g = L->pref[L->pref_sz - 1].g;
        for (int i = 0; i < R->pref_sz; ++i) {
            int ng = gcd(total_g, R->pref[i].g);
            int ncnt = R->pref[i].cnt;
            if (res.pref_sz > 0 && res.pref[res.pref_sz - 1].g == ng) {
                res.pref[res.pref_sz - 1].cnt += ncnt;
            } else {
                res.pref[res.pref_sz].g = ng;
                res.pref[res.pref_sz].cnt = ncnt;
                res.pref_sz++;
            }
        }
    }

    /* Construir os blocos de sufixo de res */
    res.suff_sz = 0;
    for (int i = 0; i < R->suff_sz; ++i) {
        res.suff[res.suff_sz++] = R->suff[i];
    }

    cur_len = 0;
    for (int i = 0; i < R->suff_sz; ++i) {
        cur_len += R->suff[i].cnt;
    }

    if (cur_len == R->len) {
        int total_g = R->suff[R->suff_sz - 1].g;
        for (int i = 0; i < L->suff_sz; ++i) {
            int ng = gcd(total_g, L->suff[i].g);
            int ncnt = L->suff[i].cnt;
            if (res.suff_sz > 0 && res.suff[res.suff_sz - 1].g == ng) {
                res.suff[res.suff_sz - 1].cnt += ncnt;
            } else {
                res.suff[res.suff_sz].g = ng;
                res.suff[res.suff_sz].cnt = ncnt;
                res.suff_sz++;
            }
        }
    }

    return res;
}

void build(int node, int l, int r) {
    if (l == r) {
        make_leaf(&tree[node], A[l]);
        return;
    }
    int mid = (l + r) / 2;
    build(2 * node, l, mid);
    build(2 * node + 1, mid + 1, r);
    tree[node] = merge(&tree[2 * node], &tree[2 * node + 1]);
}

void update(int node, int l, int r, int idx, int val) {
    if (l == r) {
        make_leaf(&tree[node], val);
        return;
    }
    int mid = (l + r) / 2;
    if (idx <= mid) {
        update(2 * node, l, mid, idx, val);
    } else {
        update(2 * node + 1, mid + 1, r, idx, val);
    }
    tree[node] = merge(&tree[2 * node], &tree[2 * node + 1]);
}

Node query(int node, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
        return tree[node];
    }
    int mid = (l + r) / 2;
    if (qr <= mid) {
        return query(2 * node, l, mid, ql, qr);
    }
    if (ql > mid) {
        return query(2 * node + 1, mid + 1, r, ql, qr);
    }
    Node left_res = query(2 * node, l, mid, ql, qr);
    Node right_res = query(2 * node + 1, mid + 1, r, ql, qr);
    return merge(&left_res, &right_res);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int i = 1; i <= N; ++i) {
        scanf("%d", &A[i]);
    }

    build(1, 1, N);

    for (int op = 0; op < M; ++op) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            int idx, val;
            scanf("%d %d", &idx, &val);
            update(1, 1, N, idx, val);
        } else {
            int l, r;
            scanf("%d %d", &l, &r);
            Node ans_node = query(1, 1, N, l, r);
            printf("%lld\n", ans_node.ans);
        }
    }

    return 0;
}
```

